(
    'Huawei Smart PV Controller Sun2000-100KTL-M2 (100KW)',
    'huawei-smart-pv-controller-sun2000-100ktl-m2-100kw',
    '#### Description:

With the Smart PV Controller Sun2000-100KTL-M2 from Huawei, transform your home into an oasis of green energy.

SUN2000 solar inverters are grid-tied PV string inverters that convert the DC power generated by PV strings into AC power and feed the power into the power grid.

Features:
- Maximum efficiency 98.8% (@480V)
- Ten independent maximum power point tracking (MPPT) circuits and 20 PV string inputs. Flexible configuration of PV strings is supported.
- Smart PV module self-learning: Automatically detects PV module failures, helping rectify faults. Optimizes the working mode to obtain the optimal working mode of the system.
- Smart air cooling: Adjusts the fan speed based on the ambient temperature and load to ensure the service life of fans and avoid frequent maintenance.
- MBUS networking: Uses the existing power line for communication and does not require additional communications cable, which reduces the construction and maintenance costs and improves communication reliability and efficiency.
- Smart I-V curve diagnosis: Implements I-V scanning and health diagnosis for PV strings. In this way, potential risks and faults can be detected in time, improving the plant operation & maintenance (O&M) quality.
- Embedded DC and AC surge protection devices (SPDs)
• Embedded residual current monitoring unit: Immediately disconnects from the power grid upon detecting that the residual current exceeds the threshold.
- SUN2000 solar inverters apply to grid-tied systems of large-scale PV plants and commercial distributed grid-tied systems. Typically, a grid-tied PV system consists of the PV string, solar inverter, AC combiner box, and transformer station.


For more inquiries, please reach out to cic@fouani.com


.',
    'Solar & Power Solutions',
    'HUWINV100KTL-M2',
    7190400,
    1045,
    'https://salva.ams3.cdn.digitaloceanspaces.com/production/tenants/fouani/picture/0/0458cd9c-557c-48eb-ac0a-c22138f58e34/image.png?_dc=1758118724',
    ARRAY['https://salva.ams3.cdn.digitaloceanspaces.com/production/tenants/fouani/picture/0/0478c538-463f-4922-ad09-58569efb4786/image.webp?_dc=1758118724', 'https://salva.ams3.cdn.digitaloceanspaces.com/production/tenants/fouani/picture/0/060a2e77-00af-4644-bc90-6e19c306a8aa/image.webp?_dc=1758118724', 'https://salva.ams3.cdn.digitaloceanspaces.com/production/tenants/fouani/picture/0/066f5d10-0cf0-4979-b54d-f9ab64f72a6c/image.webp?_dc=1758118724', 'https://salva.ams3.cdn.digitaloceanspaces.com/production/tenants/fouani/picture/7/7b1c16c4-9570-47fe-b239-f9eb0b5667f1/image.webp?_dc=1758118724', 'https://salva.ams3.cdn.digitaloceanspaces.com/production/tenants/fouani/picture/c/c2e7b0f5-7f6b-48d9-9d09-46579e4c7757/image.webp?_dc=1758118724', 'https://salva.ams3.cdn.digitaloceanspaces.com/production/tenants/fouani/picture/d/d03504f2-85fb-4523-bd14-d8c4ba6d47a7/image.webp?_dc=1758118724', 'https://salva.ams3.cdn.digitaloceanspaces.com/production/tenants/fouani/picture/f/faf05487-7212-4376-b4c9-cd6d18f20b98/image.webp?_dc=1758118724', 'https://salva.ams3.cdn.digitaloceanspaces.com/production/tenants/fouani/picture/c/c923abf0-1420-4885-b508-9a98ea2431e8/image.webp?_dc=1758118724', 'https://salva.ams3.cdn.digitaloceanspaces.com/production/tenants/fouani/picture/2/2c740458-5bf5-4a12-a64b-79d69547c048/image.webp?_dc=1758118724', 'https://salva.ams3.cdn.digitaloceanspaces.com/production/tenants/fouani/picture/b/b622a46f-8fd0-4d82-a3bc-3525dca0e272/image.webp?_dc=1758118724']::text[],
