(
    'Huawei Smart Module Controller PV Optimizer (1300 W)',
    'huawei-smart-module-controller-pv-optimizer-1300-w',
    '#### Description:

- Please note that this item cannot be returned or exchanged.
- The availability is exclusively at our Lagos main warehouse. Delivery may take longer due to logistical constraints and depending on shipping location.

The smart PV optimizer is a DC to DC converter which implements maximum power point tracking (MPPT) of each PV module to improve the energy yield of the PV system. It enables module-level shutdown and monitoring, and supports long-string design.

#### Features:

Module-level MPPT: Implements maximum power point tracking of each PV module to improve the energy yield of the PV system.
Module-level shutdown: Adjusts the module output voltage to a safe range when the output is disconnected or the inverter shuts down.

Module-level monitoring: Monitors the operating status of each PV module.
Long PV string supported: If all PV modules are configured with optimizers, a PV string can contain more PV modules than conventional PV strings.


For more inquiries, please reach out to cic@fouani.com

