    'TSTY Isolation Transformer 400kva - 400V Delta/ 400V Star (SG-M-400kva)',
    'tsty-isolation-transformer-400kva-400v-delta-400v-star-sg-m-400kva',
    '#### Description:

The TSTY Isolation Transformer 400kVA is designed to provide reliable, stable, and secure power distribution for medium to large-scale industrial and commercial operations. With 400V/400V voltage configuration, it delivers complete electrical isolation to enhance safety, protect sensitive equipment, and reduce the risks of electrical disturbances.

Engineered with durability and efficiency in mind, the SG-M-400kVA ensures clean power output, minimizes electrical noise, and prevents ground loop problems, making it ideal for facilities where consistent and dependable power is critical.

Perfect for manufacturing setups, IT infrastructure, or commercial complexes, the TSTY 400kVA Isolation Transformer is a trusted solution for safeguarding equipment while optimizing energy performance.

#### Specifications:

