    'Hisense Soundbar with Subwoofer 240W 2.1CH (HS2100)',
    'hisense-soundbar-with-subwoofer-240w-2-1ch-hs2100',
    '#### Description:

- The HS2100 Soundbar comes with 2 speakers and a wireless subwoofer that boasts a whopping 240 watts of power and superior audio performance powered by Dolby Audio Technology.

- Loud Deep Bass
The Wireless 5.25″ front firing subwoofer adds more depth to the sound bringing movies, TV and music to life with rich, powerful bass.

- DTS Virtual:X
With DTS Virtual:X, the HS2100 delivers powerful and immersive surround sound in any room.

- EzPlay
When paired with a compatible Hisense TV, EzPlay enables you to conveniently use your Hisense TV remote to control this Soundbar.

- Multiple Connections
With HDMI OUT (ARC), the Hisense HS2100 Soundbar is easy to install and connect to your TV wirelessly through Bluetooth or using a single HDMI cable.

- Multiple EQ Modes
The HS2100 comes with 6 pre-set equaliser modes – Movie Mode, Music Mode, Night Mode, News Mode, Sports Mode & Game Mode.

